var colors = ["#F3EAD5", "#B3D2B2", "#F7C280"];
var trc = ["#658179", "#1E1407", "#020302", "#CAA75C"];

var tCount = 200;
var trangX = [];
var trangY = [];



function setup() {
	createCanvas(720, 720);
	background("#060604");
	angleMode(DEGREES);
	// noLoop() removed for animation

		for (let i = 0; i < tCount; i++) {
		trangX[i] = random(-150, width + 150);
		trangY[i] = random(-150, height + 150);
	}
		tr = trianglePG();
}

function draw() {
	image(tr, 0, 0);
	for(let i = 0; i < int(random(5, 8)); i ++){
		wave();
	}

	for(let i = 0; i < 20; i++){
var x = random(-5, width + 5);
var y = random(-5, height + 5);
		strokeWeight(random(1, 10));
		stroke("#F8FDFC");
		point(x, y);
	}
	//image(tr, 0, 0);
}

function wave() {
var cx = random(width);
var cy = random(height);
var z = random(100);
var strkColor = color(253);
var alpha = map(z, 0, 100, 0, 250);

	for (let i = 0; i < width * 1.2; i += (Math.max(0.001, Math.abs(random(1)) || 1))) {
		for (let j = 0; j < 20; j += (Math.max(0.001, Math.abs(random(1)) || 1))) {
			var strkColor = color(random(colors));
			strkColor.setAlpha(alpha);
			strokeWeight(random(1));
			stroke(strkColor);

			var x = cx + i * cos(noise(j / 100, i / 1000) * 360 * 4);
			var y = cy + i * sin(noise(j / 100, i / 1000) * 360 * 2);
			point(x, y);
			//vertex(x, y);
		}
	}
}

function trianglePG() {
	pg = createGraphics(width, height);
	for (let i = 0; i < tCount - 3; i++) {
var c = color(random(trc));
		c.setAlpha(5);
		pg.noStroke();
		pg.fill(c);
		pg.triangle(trangX[i], trangX[i + 1], trangX[i + 2], trangY[i], trangY[i + 1], trangY[i + 2]);
	}
	return pg;
}
